<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Project extends Model { protected $fillable = ['code','title','customer_person_id','planned_start_date','planned_end_date','actual_start_date','actual_end_date','budget_amount','contract_total_amount','status','site_address','site_phone','description','created_by','is_active']; protected function casts(): array { return ['is_active'=>'boolean','planned_start_date'=>'date','planned_end_date'=>'date','actual_start_date'=>'date','actual_end_date'=>'date']; } public function customer() { return $this->belongsTo(Person::class,'customer_person_id'); } public function departments() { return $this->belongsToMany(Department::class,'project_departments')->withTimestamps(); } public function managers() { return $this->belongsToMany(Person::class,'project_managers')->withPivot('is_primary')->withTimestamps(); } public function contracts() { return $this->hasMany(Contract::class); } public function items() { return $this->hasMany(ProjectItem::class); } public function reportPermissions() { return $this->hasMany(ProjectCustomerReportPermission::class); } public function comments() { return $this->morphMany(Comment::class,'commentable'); } public function attachments() { return $this->morphMany(Attachment::class,'attachable'); } }
